  const writeOffListEl = contentEl.querySelector("[data-writeoff-list]");
  const writeOffEmptyEl = contentEl.querySelector("[data-writeoff-empty]");
  const writeOffCountEl = contentEl.querySelector("[data-writeoff-count]");
